CREATE EXTENSION IF NOT EXISTS postgis;
CREATE SCHEMA IF NOT EXISTS native_plants;
SET search_path=native_plants,public;
CREATE TABLE IF NOT EXISTS sources(source_id TEXT PRIMARY KEY,title TEXT NOT NULL,publisher TEXT,url TEXT,edition TEXT,retrieved_on TEXT,license TEXT,sha256 TEXT,scope_notes TEXT);
CREATE TABLE IF NOT EXISTS plants(plant_id TEXT PRIMARY KEY,accepted_scientific_name TEXT NOT NULL,scientific_name_author TEXT,preferred_common_name TEXT,family TEXT,taxon_rank TEXT NOT NULL,parent_plant_id TEXT REFERENCES plants(plant_id) DEFERRABLE INITIALLY DEFERRED,plant_form TEXT,lifecycle TEXT,description TEXT,taxonomy_source_id TEXT REFERENCES sources(source_id),identity_review_status TEXT NOT NULL CHECK(identity_review_status IN ('verified','needs_review')));
CREATE TABLE IF NOT EXISTS source_records(source_record_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(source_id),original_record_id TEXT NOT NULL,source_page INTEGER,source_row INTEGER,subset_status TEXT CHECK(subset_status IN ('native','review','excluded','original')),original_json JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS plant_source_links(source_record_id TEXT PRIMARY KEY REFERENCES source_records(source_record_id),plant_id TEXT NOT NULL REFERENCES plants(plant_id),match_status TEXT NOT NULL CHECK(match_status IN ('verified','needs_review')),match_method TEXT NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS plant_names(name_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),name TEXT NOT NULL,name_type TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(source_id));
CREATE TABLE IF NOT EXISTS external_identifiers(identifier_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),authority TEXT NOT NULL,external_taxon_id TEXT NOT NULL,source_id TEXT REFERENCES sources(source_id));
CREATE TABLE IF NOT EXISTS regions(region_id TEXT PRIMARY KEY,region_name TEXT NOT NULL,region_type TEXT NOT NULL,external_region_code TEXT,boundary_source_id TEXT REFERENCES sources(source_id),boundary_version TEXT,coverage_precision TEXT NOT NULL CHECK(coverage_precision IN ('confirmed','approximate','pending')),geom geometry(MultiPolygon,4326),notes TEXT);
CREATE TABLE IF NOT EXISTS source_coverage(coverage_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(source_id),region_id TEXT NOT NULL REFERENCES regions(region_id),coverage_role TEXT NOT NULL,coverage_status TEXT NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS regional_evidence(evidence_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),region_id TEXT NOT NULL REFERENCES regions(region_id),evidence_type TEXT NOT NULL CHECK(evidence_type IN ('native_classification','occurrence','planting_guidance')),native_status TEXT CHECK(native_status IN ('native','introduced','mixed','uncertain')),occurrence_status TEXT CHECK(occurrence_status IN ('present','historical','extirpated','uncertain')),planting_status TEXT,source_status_code TEXT,source_record_id TEXT NOT NULL REFERENCES source_records(source_record_id),evidence_date TEXT,review_status TEXT NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS trait_claims(claim_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),field_name TEXT NOT NULL,value_json JSONB NOT NULL,original_value TEXT,source_record_id TEXT NOT NULL REFERENCES source_records(source_record_id),review_status TEXT NOT NULL,qualification_notes TEXT);
CREATE TABLE IF NOT EXISTS growing_conditions(plant_id TEXT PRIMARY KEY REFERENCES plants(plant_id),soil_ph_min REAL,soil_ph_max REAL,height_min_cm REAL,height_max_cm REAL,spread_min_cm REAL,spread_max_cm REAL,bloom_start_month INTEGER,bloom_end_month INTEGER,drought_tolerance TEXT,maintenance_level TEXT,spreading_behavior TEXT,selection_provenance_json JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS condition_values(condition_value_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),field_name TEXT NOT NULL CHECK(field_name IN ('sunlight','soil_texture','soil_moisture','drainage','flower_color')),value TEXT NOT NULL,source_record_id TEXT NOT NULL REFERENCES source_records(source_record_id),is_preferred INTEGER NOT NULL CHECK(is_preferred IN (0,1)),review_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS original_plant_links(original_plant_id INTEGER PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),source_record_id TEXT NOT NULL REFERENCES source_records(source_record_id),review_status TEXT NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS import_issues(issue_id TEXT PRIMARY KEY,source_record_id TEXT REFERENCES source_records(source_record_id),issue_type TEXT NOT NULL,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_conflicts(conflict_id TEXT PRIMARY KEY,plant_id TEXT NOT NULL REFERENCES plants(plant_id),region_id TEXT REFERENCES regions(region_id),field_name TEXT NOT NULL,source_record_ids_json JSONB NOT NULL,detail TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS regions_geom_gist ON regions USING GIST(geom);
CREATE INDEX IF NOT EXISTS evidence_plant_region ON regional_evidence(plant_id,region_id);
CREATE INDEX IF NOT EXISTS names_lower_idx ON plant_names(lower(name));
CREATE OR REPLACE VIEW native_candidates AS SELECT DISTINCT p.* FROM plants p JOIN regional_evidence e ON e.plant_id=p.plant_id JOIN plant_source_links l ON l.source_record_id=e.source_record_id WHERE p.identity_review_status='verified' AND l.match_status='verified' AND e.native_status='native' AND e.occurrence_status='present' AND e.review_status='accepted_source_assertion' AND NOT EXISTS (SELECT 1 FROM evidence_conflicts f WHERE f.plant_id=p.plant_id AND f.region_id=e.region_id AND f.field_name='native_status');
CREATE OR REPLACE VIEW plant_profile AS SELECT p.*,g.height_min_cm,g.height_max_cm,g.soil_ph_min,g.soil_ph_max,g.spread_min_cm,g.spread_max_cm,g.bloom_start_month,g.bloom_end_month,g.drought_tolerance,g.maintenance_level,g.spreading_behavior,g.selection_provenance_json FROM plants p JOIN growing_conditions g ON g.plant_id=p.plant_id;
CREATE OR REPLACE VIEW identity_review_queue AS SELECT s.source_record_id,s.source_id,l.plant_id,l.match_method,l.notes FROM source_records s JOIN plant_source_links l ON l.source_record_id=s.source_record_id WHERE l.match_status='needs_review';
CREATE OR REPLACE VIEW preferred_conditions AS SELECT * FROM condition_values WHERE is_preferred=1;
